//! Port module: tiny class methods A-G (the allocator<> family and a few stubs).
//!
//! The `allocator<>` template was instantiated ~90 times, and every instantiation compiled the same
//! eight methods with different constants: `num_free` / `num_used` (a walk over a circular list),
//! `allocated_bytes`, `total_size`, `pool_bytes_required` (flag test and `count * element size`),
//! `element_size` (a constant), `release` (clears the count and a flag), `init_default_pool` (stores
//! the default pool size, then tail-jumps through vtable slot `+0x1c`) and `overhead_bytes` (two
//! virtual calls). Each instance gets its own table entry (address, whole original body, the
//! constants read from the disassembly) and its own thunk; the entry interprets the constants.
//! The same table carries the `compacting_mempool` / `async_mempool` / `gr_*_buffer` stubs that only
//! zero EAX (or AL) and pop their arguments, the constant returners, and the `deltacomp_state_data_impl`
//! `clear_dirty_mask` stores.
//!
//! Registers: every original is reproduced exactly: outputs EAX / ECX / EDX (ECX and EDX are written by
//! the arithmetic of some variants and by the list walk, so they are computed, not passed through),
//! everything else preserved. The thunk is a `pushad` block that also keeps XMM1-7 (an LTCG caller may
//! hold values there), then writes EAX / ECX / EDX back before `popad`; `ret N` where the original pops N.
//!
//! Checks:
//! - Everything but `init_default_pool` (its callee, vtable slot 0x1c, has side effects): relocated-
//!   original shadow for the first `SHADOW_CALLS` calls of each function, the stores of `release` /
//!   `clear_dirty_mask` / `async_mempool::reset` saved and restored around the original run (snapshot
//!   shadow); the original's result and writes win on a mismatch. `overhead_bytes` calls virtual
//!   `total_size` / `element_size` twice more in the shadow; those are pure reads.
//! - `init_default_pool`: counters only (the result and the callee's registers are exact by
//!   construction; the offline test compares it against the original bytes).
//! - After the window every port is the bare Rust body: one relaxed load, no logging, no allocation.
//! - Offline: `mod tests` runs each function's original bytes against its real thunk on random worlds
//!   (fake objects, circular lists, fake vtables with register-mixing stubs).

#![allow(unused_imports)]

use std::sync::atomic::{AtomicU32, AtomicUsize, Ordering};

use crate::portlib::*;
use crate::{detour, log};

const SHADOW_CALLS: u32 = 3000;

/// The `pushad` block, lowest address first.
#[repr(C)]
#[derive(Clone, Copy)]
#[allow(dead_code)] // not every register is read
struct Pushad {
    edi: u32,
    esi: u32,
    ebp: u32,
    esp: u32,
    ebx: u32,
    edx: u32,
    ecx: u32,
    eax: u32,
}

/// `pushad`, XMM1-7 saved, `entry(&mut block, &stack args, index)`, XMM1-7 restored, `popad`, `ret N`.
macro_rules! gthunk {
    ($name:ident, $idx:literal, $ret:literal) => {
        #[unsafe(naked)]
        extern "C" fn $name() {
            std::arch::naked_asm!(
                "pushad",
                "sub esp, 112",
                "movups xmmword ptr [esp], xmm1",
                "movups xmmword ptr [esp + 16], xmm2",
                "movups xmmword ptr [esp + 32], xmm3",
                "movups xmmword ptr [esp + 48], xmm4",
                "movups xmmword ptr [esp + 64], xmm5",
                "movups xmmword ptr [esp + 80], xmm6",
                "movups xmmword ptr [esp + 96], xmm7",
                "lea eax, [esp + 112]",
                "lea ecx, [esp + 148]",
                "push {idx}",
                "push ecx",
                "push eax",
                "call {f}",
                "add esp, 12",
                "movups xmm1, xmmword ptr [esp]",
                "movups xmm2, xmmword ptr [esp + 16]",
                "movups xmm3, xmmword ptr [esp + 32]",
                "movups xmm4, xmmword ptr [esp + 48]",
                "movups xmm5, xmmword ptr [esp + 64]",
                "movups xmm6, xmmword ptr [esp + 80]",
                "movups xmm7, xmmword ptr [esp + 96]",
                "add esp, 112",
                "popad",
                $ret,
                idx = const $idx,
                f = sym entry,
            )
        }
    };
}

// --- the table ---------------------------------------------------------------------------------

const K_NUM: u8 = 0; // num_free / num_used: [flag off, count off, head off, link off]
const K_ALLOC: u8 = 1; // allocated_bytes: [flag1, flag2, n off, mult, ecx mode, ecx mult, ecx add]
const K_TOTAL: u8 = 2; // total_size: [flag, const, n off, mult, add, ecx mode, ecx mult, ecx add]
const K_POOL: u8 = 3; // pool_bytes_required: [flag, n off, mult, ecx mode, ecx mult, ecx add]
const K_ELEM: u8 = 4; // element_size: [const]
const K_REL: u8 = 5; // release: [flag1 off, count off, flag2 off]
const K_INIT: u8 = 6; // init_default_pool: [flag off, pool off (test), pool off (store), const, vslot]
const K_OVH: u8 = 7; // overhead_bytes: [vslot of element_size, n off]
const K_STUB: u8 = 8; // [mode: 0 eax = 0, 1 al = 0, 2 eax = imm, 3 al = imm; imm]
const K_STORES: u8 = 9; // [eax = 0 first, width, count, first off, al + 1 (0 none)]
const KIND_NAMES: [&str; 10] = [
    "num_free_used", "allocated_bytes", "total_size", "pool_bytes_required", "element_size", "release",
    "init_default_pool", "overhead_bytes", "stubs", "stores",
];

struct E {
    addr: usize,
    name: &'static str,
    kind: u8,
    /// Bytes the original pops on return (its `ret N`).
    ret_n: u8,
    p: [u32; 8],
    body: &'static [u8],
}

#[derive(Clone, Copy, PartialEq, Eq, Default, Debug)]
struct Out {
    eax: u32,
    ecx: u32,
    edx: u32,
}

#[repr(C)]
struct CallBlock {
    f: u32,
    eax: u32,
    ecx: u32,
    edx: u32,
    esi: u32,
    edi: u32,
    args: u32,
    nargs: u32,
    o_eax: u32,
    o_ecx: u32,
    o_edx: u32,
}

/// Call `f` with these registers (EAX, ECX, EDX, ESI, EDI) and stack arguments; EAX / ECX / EDX come
/// back (EBX, EBP, ESI, EDI are the callee's to preserve).
unsafe fn callx(f: usize, r: [u32; 5], args: &[u32]) -> Out {
    let mut b = CallBlock {
        f: f as u32, eax: r[0], ecx: r[1], edx: r[2], esi: r[3], edi: r[4],
        args: args.as_ptr() as u32, nargs: args.len() as u32, o_eax: 0, o_ecx: 0, o_edx: 0,
    };
    unsafe {
        std::arch::asm!(
            "push ebx", "push ebp", "push esi", "push edi",
            "mov ebx, eax",
            "mov ebp, esp",
            "mov ecx, [ebx + 28]",
            "mov esi, [ebx + 24]",
            "2:",
            "test ecx, ecx",
            "jz 3f",
            "push dword ptr [esi + ecx*4 - 4]",
            "dec ecx",
            "jmp 2b",
            "3:",
            "mov ecx, [ebx + 8]", "mov edx, [ebx + 12]", "mov esi, [ebx + 16]", "mov edi, [ebx + 20]",
            "mov eax, [ebx + 4]",
            "call dword ptr [ebx]",
            "mov [ebx + 32], eax", "mov [ebx + 36], ecx", "mov [ebx + 40], edx",
            "mov esp, ebp",
            "pop edi", "pop esi", "pop ebp", "pop ebx",
            inout("eax") &mut b as *mut CallBlock => _,
            lateout("ecx") _,
            lateout("edx") _,
            clobber_abi("C"),
        );
    }
    Out { eax: b.o_eax, ecx: b.o_ecx, edx: b.o_edx }
}

/// The function's behaviour: `r` holds the entry registers.
#[inline(always)]
unsafe fn run(e: &E, r: &Pushad) -> Out {
    unsafe {
        let this = r.ecx as usize;
        let p = &e.p;
        let same = Out { eax: r.eax, ecx: r.ecx, edx: r.edx };
        match e.kind {
            K_NUM => {
                if rb(this + p[0] as usize) != 0 && rd(this + p[1] as usize) == 0 {
                    return Out { eax: 0, ..same };
                }
                let head = rd(this + p[2] as usize);
                let mut c = head;
                let mut n = 0u32;
                if c != 0 {
                    loop {
                        c = rd(c as usize + p[3] as usize);
                        n = n.wrapping_add(1);
                        if c == head || c == 0 {
                            break;
                        }
                    }
                }
                Out { eax: n, ecx: c, edx: head }
            }
            K_ALLOC => {
                if rb(this + p[0] as usize) == 0 || rb(this + p[1] as usize) == 0 {
                    return Out { eax: 0, ..same };
                }
                let n = rd(this + p[2] as usize);
                let ecx = if p[4] != 0 { n.wrapping_mul(p[5]).wrapping_add(p[6]) } else { r.ecx };
                Out { eax: n.wrapping_mul(p[3]), ecx, edx: r.edx }
            }
            K_TOTAL => {
                if rb(this + p[0] as usize) != 0 {
                    return Out { eax: p[1], ..same };
                }
                let n = rd(this + p[2] as usize);
                let ecx = if p[5] != 0 { n.wrapping_mul(p[6]).wrapping_add(p[7]) } else { r.ecx };
                Out { eax: n.wrapping_mul(p[3]).wrapping_add(p[4]), ecx, edx: r.edx }
            }
            K_POOL => {
                if rb(this + p[0] as usize) == 0 {
                    return Out { eax: 0, ..same };
                }
                let n = rd(this + p[1] as usize);
                let ecx = if p[3] != 0 { n.wrapping_mul(p[4]).wrapping_add(p[5]) } else { r.ecx };
                Out { eax: n.wrapping_mul(p[2]), ecx, edx: r.edx }
            }
            K_ELEM => Out { eax: p[0], ..same },
            K_REL => {
                if rb(this + p[0] as usize) != 0 && rd(this + p[1] as usize) != 0 {
                    wd(this + p[1] as usize, 0);
                    wb(this + p[2] as usize, 0);
                }
                Out { eax: 0, ..same }
            }
            K_INIT => {
                if rb(this + p[0] as usize) == 0 {
                    return same;
                }
                if rd(this + p[1] as usize) == 0 {
                    wd(this + p[2] as usize, p[3]);
                }
                let vt = rd(this);
                let f = rd(vt as usize + p[4] as usize);
                callx(f as usize, [vt, r.ecx, f, r.esi, r.edi], &[])
            }
            K_OVH => {
                let vt = rd(this);
                let f1 = rd(vt as usize + p[0] as usize);
                let a = callx(f1 as usize, [vt, r.ecx, f1, r.ecx, r.edi], &[]);
                let edi = a.eax.wrapping_mul(rd(this + p[1] as usize));
                let vt2 = rd(this);
                let f2 = rd(vt2 as usize + 4);
                let b = callx(f2 as usize, [vt2, r.ecx, f2, r.ecx, edi], &[]);
                Out { eax: b.eax.wrapping_sub(edi), ecx: b.ecx, edx: b.edx }
            }
            K_STUB => {
                let eax = match p[0] {
                    0 => 0,
                    1 => r.eax & !0xFF,
                    2 => p[1],
                    _ => (r.eax & !0xFF) | (p[1] & 0xFF),
                };
                Out { eax, ..same }
            }
            _ => {
                // K_STORES: zero stores, then optionally `mov al, imm`.
                let mut eax = if p[0] != 0 { 0 } else { r.eax };
                let base = this + p[3] as usize;
                for i in 0..p[2] as usize {
                    match p[1] {
                        2 => std::ptr::write_unaligned((base + i * 2) as *mut u16, 0),
                        1 => wb(base + i, 0),
                        _ => wd(base + i * 4, 0),
                    }
                }
                if p[4] != 0 {
                    eax = (eax & !0xFF) | (p[4] - 1);
                }
                Out { eax, ..same }
            }
        }
    }
}

// --- shadow machinery --------------------------------------------------------------------------

struct St {
    calls: AtomicU32,
    mismatches: AtomicU32,
    /// A copy of the original (0 = none: not shadowed).
    original: AtomicUsize,
}

#[allow(clippy::declare_interior_mutable_const)]
const ST0: St = St { calls: AtomicU32::new(0), mismatches: AtomicU32::new(0), original: AtomicUsize::new(0) };
static STATE: [St; COUNT] = [ST0; COUNT];

/// The memory the function may write (address, length), at most two ranges.
fn write_ranges(e: &E, this: usize) -> [(usize, usize); 2] {
    let p = &e.p;
    match e.kind {
        K_REL => [(this + p[1] as usize, 4), (this + p[2] as usize, 1)],
        K_STORES => [(this + p[3] as usize, p[1] as usize * p[2] as usize), (0, 0)],
        _ => [(0, 0), (0, 0)],
    }
}

#[cold]
#[inline(never)]
unsafe fn shadow_slow(idx: usize, r: &Pushad, args: *const u32) -> Out {
    let e = &TABLE[idx];
    let st = &STATE[idx];
    let n = st.calls.fetch_add(1, Ordering::Relaxed);
    let orig = st.original.load(Ordering::Relaxed);
    unsafe {
        if orig == 0 {
            return run(e, r);
        }
        let rg = write_ranges(e, r.ecx as usize);
        let mut s0 = [0u8; 32];
        let mut s1 = [0u8; 32];
        let mut s2 = [0u8; 32];
        let save = |buf: &mut [u8; 32]| {
            let mut o = 0;
            for &(a, l) in &rg {
                if l != 0 {
                    std::ptr::copy_nonoverlapping(a as *const u8, buf.as_mut_ptr().add(o), l);
                    o += l;
                }
            }
        };
        let restore = |buf: &[u8; 32]| {
            let mut o = 0;
            for &(a, l) in &rg {
                if l != 0 {
                    std::ptr::copy_nonoverlapping(buf.as_ptr().add(o), a as *mut u8, l);
                    o += l;
                }
            }
        };
        let total: usize = rg.iter().map(|x| x.1).sum();
        let nargs = (e.ret_n / 4) as usize;
        let a: &[u32] = if nargs == 0 { &[] } else { std::slice::from_raw_parts(args, nargs) };
        save(&mut s0);
        let o = callx(orig, [r.eax, r.ecx, r.edx, r.esi, r.edi], a);
        save(&mut s1);
        restore(&s0);
        let ours = run(e, r);
        save(&mut s2);
        if o == ours && s1[..total] == s2[..total] {
            return ours;
        }
        restore(&s1);
        let m = st.mismatches.fetch_add(1, Ordering::Relaxed) + 1;
        if m <= 10 {
            log(&format!(
                "port_small_a: {} @ {:#x} mismatch (call {n}): regs eax {:#x} ecx {:#x} edx {:#x} esi {:#x} edi {:#x}: original {:x?} Rust {:x?}",
                e.name, e.addr, r.eax, r.ecx, r.edx, r.esi, r.edi, o, ours
            ));
        }
        o
    }
}

extern "C" fn entry(r: &mut Pushad, args: *const u32, idx: u32) {
    let idx = idx as usize;
    let out = unsafe {
        if STATE[idx].calls.load(Ordering::Relaxed) >= SHADOW_CALLS {
            run(&TABLE[idx], r)
        } else {
            shadow_slow(idx, r, args)
        }
    };
    r.eax = out.eax;
    r.ecx = out.ecx;
    r.edx = out.edx;
}

