// --- install -----------------------------------------------------------------------------------

/// Install this module's replacements (called from hooks::install_all).
pub fn install() {
    use windows_sys::Win32::System::Memory::{MEM_COMMIT, MEM_RESERVE, PAGE_EXECUTE_READWRITE, VirtualAlloc};
    // One executable block holds the shadow copies of the originals (every body is position independent:
    // short internal branches, indirect calls and jumps only).
    let need: usize = TABLE.iter().filter(|e| e.kind != K_INIT).map(|e| (e.body.len() + 15) & !15).sum();
    let block = unsafe { VirtualAlloc(std::ptr::null(), need, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE) } as usize;
    let mut next = block;
    let mut ok = 0;
    for (i, e) in TABLE.iter().enumerate() {
        let current = unsafe { std::slice::from_raw_parts(e.addr as *const u8, e.body.len()) };
        if current != e.body {
            log(&format!("port_small_a: {} @ {:#x}: the exe's bytes differ, not replaced", e.name, e.addr));
            continue;
        }
        if block != 0 && e.kind != K_INIT {
            unsafe { std::ptr::copy_nonoverlapping(e.body.as_ptr(), next as *mut u8, e.body.len()) };
            STATE[i].original.store(next, Ordering::Relaxed);
            next += (e.body.len() + 15) & !15;
        }
        if replace_pinned(e.name, e.addr, e.body, THUNKS[i] as usize) {
            ok += 1;
        }
    }
    log(&format!("port_small_a: replaced {ok}/{COUNT} with Rust"));
}

/// Per-kind call counts for the periodic log (the first `SHADOW_CALLS` calls of each function are counted).
pub fn summary() -> String {
    let mut calls = [0u64; KIND_NAMES.len()];
    let mut bad = [0u64; KIND_NAMES.len()];
    for (i, e) in TABLE.iter().enumerate() {
        calls[e.kind as usize] += STATE[i].calls.load(Ordering::Relaxed) as u64;
        bad[e.kind as usize] += STATE[i].mismatches.load(Ordering::Relaxed) as u64;
    }
    let parts: Vec<String> = (0..KIND_NAMES.len())
        .filter(|&k| calls[k] > 0)
        .map(|k| format!("{} {} ({} shadow mismatches)", KIND_NAMES[k], calls[k], bad[k]))
        .collect();
    if parts.is_empty() {
        return String::new();
    }
    format!("port_small_a: {}", parts.join(", "))
}

// =================================================================================================
// Offline differential test
// =================================================================================================
//
// Each test runs a function's ORIGINAL bytes (copied to executable memory) and the Rust port through
// its real thunk on the same random world and compares EAX / ECX / EDX, every register the original
// preserves, XMM1-7, the x87 depth, the stack pointer after the return (the `ret N`) and every word of
// the arena the pointers point into. Virtual calls go to stubs that mix every input register into
// their outputs.
//
// Run (one test per process):
//   RUSTFLAGS="-C target-feature=+crt-static -C link-arg=/DYNAMICBASE:NO -C link-arg=/BASE:0x10000000" cargo test --release
//   -p sr2-hook --target i686-pc-windows-msvc port_small_a -- --ignored --test-threads=1 --nocapture
// (CASES=n changes the number of random cases per function, default 1500; KIND=name restricts a test.)

#[cfg(test)]
mod tests {
    use super::*;
    use windows_sys::Win32::System::Memory::{MEM_COMMIT, MEM_RESERVE, PAGE_EXECUTE_READWRITE, VirtualAlloc};

    #[repr(C)]
    #[derive(Clone, Copy)]
    struct TB {
        f: u32,
        eax: u32,
        ecx: u32,
        edx: u32,
        ebx: u32,
        esi: u32,
        edi: u32,
        ebp: u32,
        args: u32,
        nargs: u32,
        o_eax: u32,
        o_ecx: u32,
        o_edx: u32,
        o_ebx: u32,
        o_esi: u32,
        o_edi: u32,
        o_ebp: u32,
        top0: u32,
        top1: u32,
        esp: u32,
        xmm: [u32; 32],
        st0: u64,
        esp_after: u32,
    }

    static mut SLOTS: [u32; 3] = [0; 3];

    #[derive(Clone, Copy)]
    struct In {
        eax: u32,
        ecx: u32,
        edx: u32,
        esi: u32,
        edi: u32,
    }

    const EBX_IN: u32 = 0xB1B1_B1B1;
    const EBP_IN: u32 = 0xE9E9_E9E9;

    fn xmm_pattern() -> [u32; 32] {
        let mut x = [0u32; 32];
        for (i, w) in x.iter_mut().enumerate() {
            *w = 0x3F00_0000 + (i as u32) * 0x0101_0101;
        }
        x
    }

    /// Call `f` with these registers and stack arguments (53-bit x87, clean stack); capture everything.
    unsafe fn call_t(f: usize, r: In, args: &[u32]) -> TB {
        let mut b = TB {
            f: f as u32, eax: r.eax, ecx: r.ecx, edx: r.edx, ebx: EBX_IN, esi: r.esi, edi: r.edi, ebp: EBP_IN,
            args: args.as_ptr() as u32, nargs: args.len() as u32,
            o_eax: 0, o_ecx: 0, o_edx: 0, o_ebx: 0, o_esi: 0, o_edi: 0, o_ebp: 0, top0: 0, top1: 0, esp: 0,
            xmm: xmm_pattern(), st0: 0, esp_after: 0,
        };
        unsafe {
            let slots = std::ptr::addr_of_mut!(SLOTS);
            (*slots)[0] = &mut b as *mut TB as u32;
            (*slots)[1] = f as u32;
            std::arch::asm!(
                "push ebp", "push ebx", "push esi", "push edi",
                "mov [eax + 76], esp",
                "mov [{s}], eax",
                "mov ebx, eax",
                "fninit",
                "push 0x27F",
                "fldcw word ptr [esp]",
                "add esp, 4",
                "movups xmm0, xmmword ptr [ebx + 80]",
                "movups xmm1, xmmword ptr [ebx + 96]",
                "movups xmm2, xmmword ptr [ebx + 112]",
                "movups xmm3, xmmword ptr [ebx + 128]",
                "movups xmm4, xmmword ptr [ebx + 144]",
                "movups xmm5, xmmword ptr [ebx + 160]",
                "movups xmm6, xmmword ptr [ebx + 176]",
                "movups xmm7, xmmword ptr [ebx + 192]",
                "mov ecx, [ebx + 36]",
                "mov esi, [ebx + 32]",
                "2:",
                "test ecx, ecx",
                "jz 3f",
                "push dword ptr [esi + ecx*4 - 4]",
                "dec ecx",
                "jmp 2b",
                "3:",
                "fnstsw word ptr [ebx + 68]",
                "mov ecx, [ebx + 8]", "mov edx, [ebx + 12]", "mov esi, [ebx + 20]", "mov edi, [ebx + 24]",
                "mov ebp, [ebx + 28]", "mov eax, [ebx + 4]", "mov ebx, [ebx + 16]",
                "call dword ptr [{s} + 4]",
                "mov [{s} + 8], esp",
                "push eax",
                "mov eax, dword ptr [{s}]",
                "mov [eax + 44], ecx", "mov [eax + 48], edx", "mov [eax + 52], ebx", "mov [eax + 56], esi",
                "mov [eax + 60], edi", "mov [eax + 64], ebp",
                "pop dword ptr [eax + 40]",
                "movups xmmword ptr [eax + 80], xmm0",
                "movups xmmword ptr [eax + 96], xmm1",
                "movups xmmword ptr [eax + 112], xmm2",
                "movups xmmword ptr [eax + 128], xmm3",
                "movups xmmword ptr [eax + 144], xmm4",
                "movups xmmword ptr [eax + 160], xmm5",
                "movups xmmword ptr [eax + 176], xmm6",
                "movups xmmword ptr [eax + 192], xmm7",
                "fnstsw word ptr [eax + 72]",
                "movzx ecx, word ptr [eax + 72]",
                "and ecx, 0x3800",
                "movzx edx, word ptr [eax + 68]",
                "and edx, 0x3800",
                "cmp ecx, edx",
                "je 5f",
                "fstp qword ptr [eax + 208]",
                "5:",
                "mov ecx, [{s} + 8]",
                "mov [eax + 216], ecx",
                "mov esp, [eax + 76]",
                "pop edi", "pop esi", "pop ebx", "pop ebp",
                s = sym SLOTS,
                inout("eax") &mut b as *mut TB => _,
                clobber_abi("C"),
            );
        }
        b
    }

    fn exec_alloc(len: usize) -> usize {
        let p = unsafe { VirtualAlloc(std::ptr::null(), len, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE) } as usize;
        assert!(p != 0);
        p
    }

    fn exec_copy(body: &[u8]) -> usize {
        let p = exec_alloc(body.len() + 16);
        unsafe { std::ptr::copy_nonoverlapping(body.as_ptr(), p as *mut u8, body.len()) };
        p
    }

    /// 32 stubs, stub i at `base + 32 * i`: every input register is mixed into the outputs.
    fn stubs() -> usize {
        static BASE: AtomicUsize = AtomicUsize::new(0);
        let b = BASE.load(Ordering::Relaxed);
        if b != 0 {
            return b;
        }
        let p = exec_alloc(32 * 32);
        for i in 0..32usize {
            let mut c: Vec<u8> = vec![
                0x8D, 0x04, 0x10, // lea eax,[eax+edx]
                0x01, 0xF0, // add eax,esi
                0x01, 0xF8, // add eax,edi
                0x03, 0x41, 0x1C, // add eax,[ecx+0x1c]
                0x03, 0x41, 0x18, // add eax,[ecx+0x18]
                0x05,
            ];
            c.extend_from_slice(&(0x100 + i as u32 * 7).to_le_bytes()); // add eax, imm32
            c.extend_from_slice(&[0x8D, 0x14, 0x39]); // lea edx,[ecx+edi]
            c.extend_from_slice(&[0x8D, 0x49, (i + 1) as u8]); // lea ecx,[ecx+i+1]
            c.push(0xC3);
            assert!(c.len() <= 32);
            unsafe { std::ptr::copy_nonoverlapping(c.as_ptr(), (p + i * 32) as *mut u8, c.len()) };
        }
        BASE.store(p, Ordering::Relaxed);
        p
    }

    struct Rng(u64);
    impl Rng {
        fn u32(&mut self) -> u32 {
            self.0 ^= self.0 << 13;
            self.0 ^= self.0 >> 7;
            self.0 ^= self.0 << 17;
            (self.0 >> 16) as u32
        }
        fn below(&mut self, n: u32) -> u32 {
            self.u32() % n
        }
        /// 0, 1, small, or any value.
        fn mixed(&mut self) -> u32 {
            match self.below(5) {
                0 => 0,
                1 => 1,
                2 => self.below(40),
                _ => self.u32(),
            }
        }
    }

    const ARENA_WORDS: usize = 4096;
    const THIS_W: usize = 64;
    const VT_W: usize = 300;
    const NODE_W: usize = 1000;

    fn cases() -> u32 {
        std::env::var("CASES").ok().and_then(|v| v.parse().ok()).unwrap_or(1500)
    }

    fn ptr(arena: &Vec<u32>, word: usize) -> u32 {
        arena.as_ptr() as u32 + (word as u32) * 4
    }

    fn put_b(arena: &mut Vec<u32>, byte_off: usize, v: u8) {
        unsafe { *((arena.as_mut_ptr() as *mut u8).add(byte_off)) = v };
    }

    fn put_d(arena: &mut Vec<u32>, byte_off: usize, v: u32) {
        unsafe { std::ptr::write_unaligned((arena.as_mut_ptr() as *mut u8).add(byte_off) as *mut u32, v) };
    }

    fn flag(rng: &mut Rng) -> u8 {
        match rng.below(4) {
            0 => 0,
            1 => 1,
            2 => 0xFF,
            _ => rng.u32() as u8,
        }
    }

    /// Build a random world for `e`; returns the entry registers.
    fn world(e: &E, rng: &mut Rng, arena: &mut Vec<u32>) -> In {
        for w in arena.iter_mut() {
            *w = rng.mixed();
        }
        let this = ptr(arena, THIS_W);
        let tb = THIS_W * 4; // byte offset of the object in the arena
        let p = &e.p;
        let vt = ptr(arena, VT_W);
        let st = stubs();
        for i in 0..32 {
            arena[VT_W + i] = (st + i * 32) as u32;
        }
        match e.kind {
            K_NUM => {
                put_b(arena, tb + p[0] as usize, flag(rng));
                put_d(arena, tb + p[1] as usize, if rng.below(3) == 0 { 0 } else { rng.mixed() });
                // nodes: zeroed, 0x100 bytes apart, chained through the link field
                for w in NODE_W..NODE_W + 12 * 64 {
                    arena[w] = 0;
                }
                let nn = rng.below(10) as usize;
                let first = if nn == 0 { 0 } else { rng.below(nn as u32) as usize };
                let kind = rng.below(4);
                for i in 0..nn {
                    let next = if i + 1 < nn {
                        ptr(arena, NODE_W + (i + 1) * 64)
                    } else if kind == 0 {
                        0
                    } else {
                        ptr(arena, NODE_W + first * 64)
                    };
                    let next = if kind == 3 && i == nn / 2 && i >= first { ptr(arena, NODE_W + first * 64) } else { next };
                    put_d(arena, NODE_W * 4 + i * 256 + p[3] as usize, next);
                }
                let head = if nn == 0 { 0 } else { ptr(arena, NODE_W + first * 64) };
                put_d(arena, tb + p[2] as usize, head);
            }
            K_ALLOC => {
                put_b(arena, tb + p[0] as usize, flag(rng));
                put_b(arena, tb + p[1] as usize, flag(rng));
                put_d(arena, tb + p[2] as usize, rng.mixed());
            }
            K_TOTAL => {
                put_b(arena, tb + p[0] as usize, flag(rng));
                put_d(arena, tb + p[2] as usize, rng.mixed());
            }
            K_POOL => {
                put_b(arena, tb + p[0] as usize, flag(rng));
                put_d(arena, tb + p[1] as usize, rng.mixed());
            }
            K_REL => {
                put_b(arena, tb + p[0] as usize, flag(rng));
                put_d(arena, tb + p[1] as usize, rng.mixed());
                put_b(arena, tb + p[2] as usize, flag(rng));
            }
            K_INIT => {
                put_d(arena, tb, vt);
                put_b(arena, tb + p[0] as usize, flag(rng));
                put_d(arena, tb + p[1] as usize, if rng.below(2) == 0 { 0 } else { rng.u32() & 0xFFFF });
            }
            K_OVH => {
                put_d(arena, tb, vt);
                put_d(arena, tb + p[1] as usize, rng.mixed());
            }
            _ => {}
        }
        // the 0x1c / 0x18 fields the stubs read must stay readable and mixed (they are arena words)
        In { eax: rng.u32(), ecx: this, edx: rng.u32(), esi: rng.u32(), edi: rng.u32() }
    }

    fn run_kinds(kinds: &[u8], seed: u64) {
        let only = std::env::var("KIND").ok();
        let n = cases();
        let mut total_cases = 0u64;
        let mut funcs = 0;
        let mut fails = 0u32;
        let mut arena = vec![0u32; ARENA_WORDS];
        for (idx, e) in TABLE.iter().enumerate() {
            if !kinds.contains(&e.kind) {
                continue;
            }
            if let Some(k) = &only {
                if KIND_NAMES[e.kind as usize] != k {
                    continue;
                }
            }
            funcs += 1;
            let orig = exec_copy(e.body);
            let thunk = THUNKS[idx] as *const () as usize;
            let mut rng = Rng(seed ^ (e.addr as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1);
            let mut bad = 0;
            for i in 0..n {
                let r = world(e, &mut rng, &mut arena);
                let args: Vec<u32> = (0..e.ret_n / 4).map(|_| rng.u32()).collect();
                let snap = arena.clone();
                let o = unsafe { call_t(orig, r, &args) };
                let a1 = arena.clone();
                arena.copy_from_slice(&snap);
                let t = unsafe { call_t(thunk, r, &args) };
                let a2 = arena.clone();
                arena.copy_from_slice(&snap);
                let mut err = String::new();
                if (o.o_eax, o.o_ecx, o.o_edx) != (t.o_eax, t.o_ecx, t.o_edx) {
                    err += &format!(" eax/ecx/edx original {:#x}/{:#x}/{:#x} Rust {:#x}/{:#x}/{:#x};", o.o_eax, o.o_ecx, o.o_edx, t.o_eax, t.o_ecx, t.o_edx);
                }
                if (t.o_ebx, t.o_esi, t.o_edi, t.o_ebp) != (o.o_ebx, o.o_esi, o.o_edi, o.o_ebp) || t.o_ebx != EBX_IN || t.o_ebp != EBP_IN || t.o_esi != r.esi || t.o_edi != r.edi {
                    err += &format!(" preserved registers: original ebx {:#x} esi {:#x} edi {:#x} ebp {:#x}, Rust ebx {:#x} esi {:#x} edi {:#x} ebp {:#x};", o.o_ebx, o.o_esi, o.o_edi, o.o_ebp, t.o_ebx, t.o_esi, t.o_edi, t.o_ebp);
                }
                if t.xmm[4..] != xmm_pattern()[4..] || o.xmm[4..] != xmm_pattern()[4..] {
                    err += " xmm1-7 changed;";
                }
                let od = ((o.top0 & 0x3800).wrapping_sub(o.top1 & 0x3800) & 0x3800) >> 11;
                let td = ((t.top0 & 0x3800).wrapping_sub(t.top1 & 0x3800) & 0x3800) >> 11;
                if od != td || td != 0 {
                    err += &format!(" x87 depth original {od} Rust {td};");
                }
                if o.esp_after != t.esp_after {
                    err += &format!(" esp after: original {:#x} Rust {:#x} (ret N);", o.esp_after, t.esp_after);
                }
                if a1 != a2 {
                    let w = a1.iter().zip(&a2).position(|(x, y)| x != y).unwrap();
                    err += &format!(" arena word {w}: original {:#x} Rust {:#x};", a1[w], a2[w]);
                }
                if !err.is_empty() {
                    bad += 1;
                    if bad <= 3 {
                        eprintln!("{} @ {:#x} case {i}:{err}", e.name, e.addr);
                    }
                }
            }
            if bad != 0 {
                fails += 1;
            }
            total_cases += n as u64;
        }
        eprintln!("{funcs} functions, {total_cases} cases, {fails} functions differ");
        assert!(funcs > 0);
        assert_eq!(fails, 0);
    }

    #[test]
    #[ignore = "offline differential test (see the comment above)"]
    fn num_matches_original() {
        run_kinds(&[K_NUM], 0x1111_2222_3333_4444);
    }

    #[test]
    #[ignore = "offline differential test (see the comment above)"]
    fn sizes_match_original() {
        run_kinds(&[K_ALLOC, K_TOTAL, K_POOL, K_ELEM], 0x5555_6666_7777_8888);
    }

    #[test]
    #[ignore = "offline differential test (see the comment above)"]
    fn release_matches_original() {
        run_kinds(&[K_REL], 0x9999_AAAA_BBBB_CCCC);
    }

    #[test]
    #[ignore = "offline differential test (see the comment above)"]
    fn virtual_calls_match_original() {
        run_kinds(&[K_INIT, K_OVH], 0x0123_4567_89AB_CDEF);
    }

    #[test]
    #[ignore = "offline differential test (see the comment above)"]
    fn stubs_match_original() {
        run_kinds(&[K_STUB, K_STORES], 0x0FED_CBA9_8765_4321);
    }

    /// The in-thunk shadow (original run and compared inside the port) must agree on every kind, and
    /// must notice a difference: one entry's table row is not altered, so the control flips the
    /// original's copy to a different function's bytes and expects mismatches.
    #[test]
    #[ignore = "offline differential test (see the comment above)"]
    fn shadow_agrees_and_detects() {
        let mut rng = Rng(0x7777_AAAA_1357_9BDF);
        let mut arena = vec![0u32; ARENA_WORDS];
        let mut seen = [false; KIND_NAMES.len()];
        let mut total = 0;
        for (idx, e) in TABLE.iter().enumerate() {
            if seen[e.kind as usize] || e.kind == K_INIT {
                continue;
            }
            seen[e.kind as usize] = true;
            STATE[idx].original.store(exec_copy(e.body), Ordering::Relaxed);
            STATE[idx].calls.store(0, Ordering::Relaxed);
            STATE[idx].mismatches.store(0, Ordering::Relaxed);
            let thunk = THUNKS[idx] as *const () as usize;
            for _ in 0..300 {
                let r = world(e, &mut rng, &mut arena);
                let args: Vec<u32> = (0..e.ret_n / 4).map(|_| rng.u32()).collect();
                unsafe { call_t(thunk, r, &args) };
                total += 1;
            }
            assert_eq!(STATE[idx].mismatches.load(Ordering::Relaxed), 0, "{}", e.name);
            assert_eq!(STATE[idx].calls.load(Ordering::Relaxed), 300);
        }
        eprintln!("shadow: {total} calls over {} kinds, no mismatches", seen.iter().filter(|&&s| s).count());
        // control: an ELEM entry whose shadow copy is a different member (another constant) must be reported
        let a = TABLE.iter().position(|e| e.kind == K_ELEM).unwrap();
        let b = TABLE.iter().position(|e| e.kind == K_ELEM && e.p[0] != TABLE[a].p[0]).unwrap();
        STATE[a].original.store(exec_copy(TABLE[b].body), Ordering::Relaxed);
        STATE[a].calls.store(0, Ordering::Relaxed);
        STATE[a].mismatches.store(0, Ordering::Relaxed);
        let thunk = THUNKS[a] as *const () as usize;
        let r = world(&TABLE[a], &mut rng, &mut arena);
        let t = unsafe { call_t(thunk, r, &[]) };
        assert_eq!(t.o_eax, TABLE[b].p[0], "on a mismatch the original's result must win");
        assert!(STATE[a].mismatches.load(Ordering::Relaxed) > 0, "the shadow missed a different original");
    }
}
